const P=[['Nora','regissør',PLACES[0],'holder kunstnerisk intensjon, scenisk handling, rytme og beslutningsstatus samlet gjennom prøveperioden','kan beslutte regi innen delegert mandat, men kan ikke presse utøvere forbi samtykke/HMS, overstyre teknisk sikkerhet eller anta rettigheter'],['Amir','koreograf',PLACES[1],'utvikler bevegelsesmateriale, fysisk komposisjon og relasjon mellom kropper, rom og timing med eksplisitt belastnings- og samtykkespor','kan forme koreografi innen mandat, men kan ikke gjøre smerte, intim kontakt eller uforsvarlig belastning til obligatorisk kunstnerisk bevis'],['Signe','inspisient',PLACES[2],'bevarer prøvebok, call, gjennomløpsstatus, noter, låste overganger og avhengigheter slik at samme versjon når ensemble og teknikk','kan koordinere og kreve entydig gjeldende versjon, men eier ikke kunstnerisk tolkning og gjør ikke foreløpig note til godkjenning'],['Even','teknisk leder',PLACES[3],'oversetter sceniske ønsker til rigg, maskineri, lys, lyd, gulv, tid og sikkerhetsmessige premisser og prøvbare alternativer','kan stoppe teknisk uforsvarlige løsninger og kreve ny test, men bestemmer ikke kunstnerisk kvalitet og kan ikke presses av premierefrist']].map((x,i)=>({id:ACTORS[i],name:x[0],role:x[1],workplace_ids:[x[2]],fictional:true,fictional_scenario_actor:true,canonical_person_ref:null,function:`${x[0]} ${x[3]}. Rollen arbeider mot samme proveromsbok, der mål, versjon, observasjon, note, beslutningseier, avhengighet og neste prøve beholdes over venting og senere rework, slik at arbeidet kan overtas uten skjult kontekst.`,authority_relation:`${x[0]} ${x[4]}. Spilleren kan foreslå og teste kunstneriske løsninger, men må alltid markere hvem som eier samtykke, sikkerhet, rettighet, gjennomføringsbeslutning og endelig låsing, og overlevere når et annet mandat tar over.`}));for(const p of P)if(p.function.length<220||p.authority_relation.length<220)throw Error(p.id+' depth');
